head.b:skin:
*{box-sizing:border-box}
body{margin:0;background:#fff;font-family:Arial,Helvetica,sans-serif;color:#222;font-size:14px;line-height:1.55}
a{color:#0645d9;text-decoration:none}
a:hover{text-decoration:underline}
img{max-width:100%;height:auto}
.site-wrap{max-width:980px;margin:0 auto;background:#fff}
.site-header{background:#a40000;color:#fff;text-align:center;padding:15px 10px}
.site-header h1{margin:0;font-size:32px;line-height:1.05;font-weight:700}
.site-header h1 a{color:#fff;text-decoration:none}
.site-header p{margin:4px 0 0;font-size:13px}
.top-nav{display:flex;flex-wrap:wrap;justify-content:center;background:#073a8c;border-bottom:3px solid #ffcc00}
.top-nav a{color:#fff;text-decoration:none;padding:8px 11px;font-size:13px;font-weight:700;border-right:1px solid rgba(255,255,255,.22)}
.ticker{text-align:center;font-size:13px;padding:8px;border-bottom:1px solid #ddd}
.ticker a{font-weight:700}
.quick-links{display:grid;grid-template-columns:repeat(4,1fr);gap:4px;margin:10px 0}
.quick-links a{color:#fff;text-align:center;text-decoration:none;padding:8px 5px;font-weight:700;font-size:13px;min-height:38px;display:flex;align-items:center;justify-content:center}
.quick-links a:nth-child(1){background:#f97316}.quick-links a:nth-child(2){background:#16a34a}.quick-links a:nth-child(3){background:#2563eb}.quick-links a:nth-child(4){background:#dc2626}
.quick-links a:nth-child(5){background:#db2777}.quick-links a:nth-child(6){background:#7c3aed}.quick-links a:nth-child(7){background:#0891b2}.quick-links a:nth-child(8){background:#15803d}
.hero-ad{background:#1f2937;color:#fff;min-height:96px;margin:10px 0;border-radius:4px;display:flex;align-items:center;justify-content:center;text-align:center;padding:16px;font-weight:700}
.homepage-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:12px 0}
.job-box{border:1px solid #bdbdbd;background:#fff;min-height:260px}
.job-box h2{background:#a40000;color:#fff;font-size:16px;margin:0;padding:7px;text-align:center}
.job-box ul{margin:0;padding:8px 8px 8px 24px;min-height:220px}
.job-box li{margin:0 0 7px;font-size:13px;line-height:1.35}
.more-link{display:block;margin:0 8px 8px auto;width:max-content;background:#1d70b8;color:#fff!important;text-decoration:none;padding:5px 8px;border-radius:2px;font-size:12px}
.intro-content{margin:18px 0;font-size:14px;line-height:1.7}
.intro-content h2{font-size:22px;margin:14px 0 8px;color:#333}
.main-area{margin-top:12px}
.blog-posts{margin:0}
.post-outer{border:1px solid #ddd;margin:0 0 12px;padding:12px;background:#fff}
.post-title,.post-title a{font-size:22px;color:#a40000;margin:0 0 8px;text-decoration:none}
.post-body{font-size:15px;line-height:1.7}
.post-body h2{background:#b91c1c;color:#fff;font-size:18px;margin:18px 0 8px;padding:8px 10px;border-radius:3px}
.post-body table{width:100%;border-collapse:collapse;margin:10px 0}
.post-body th,.post-body td{border:1px solid #d1d5db;padding:9px;text-align:left;vertical-align:top}
.post-body th{background:#f3f4f6}
.footer{background:#3b82f6;color:#fff;text-align:center;padding:15px;font-size:13px;margin-top:20px}
.footer a{color:#fff}
@media(max-width:760px){
  .site-wrap{width:100%;padding:0 8px}
  .site-header h1{font-size:25px}
  .homepage-grid{grid-template-columns:1fr}
  .quick-links{grid-template-columns:repeat(2,1fr)}
  .top-nav a{font-size:12px;padding:8px}
  .post-title,.post-title a{font-size:19px}
  .post-body th,.post-body td{display:block;width:100%}
}

body.script:
//
  function loadLabelPosts(label, targetId, fallbackLabel){
    var target=document.getElementById(targetId);
    if(!target){return;}
    var url='/feeds/posts/default/-/'+encodeURIComponent(label)+'?alt=json&max-results=12';
    fetch(url).then(function(r){return r.json();}).then(function(data){
      var entries=(data.feed&&data.feed.entry)?data.feed.entry:[];
      if(!entries.length && fallbackLabel){
        return loadLabelPosts(fallbackLabel,targetId);
      }
      target.innerHTML='';
      entries.slice(0,10).forEach(function(entry){
        var link='#';
        (entry.link||[]).forEach(function(item){if(item.rel==='alternate'){link=item.href;}});
        var li=document.createElement('li');
        var a=document.createElement('a');
        a.href=link;
        a.textContent=entry.title.$t;
        li.appendChild(a);
        target.appendChild(li);
      });
      if(!target.children.length){target.innerHTML='<li>No posts found</li>';}
    }).catch(function(){target.innerHTML='<li>No posts found</li>';});
  }
  if(document.body){
    loadLabelPosts('Results','box-results');
    loadLabelPosts('Admit Card','box-admit');
    loadLabelPosts('Latest Jobs','box-latest');
    loadLabelPosts('Answer Key','box-answer');
    loadLabelPosts('Syllabus','box-syllabus');
    loadLabelPosts('Admission','box-admission','Latest Jobs');
    loadLabelPosts('Document Verification','box-docs','Latest Jobs');
    loadLabelPosts('ITI','box-iti','Latest Jobs');
    loadLabelPosts('Private Jobs','box-tech','Latest Jobs');
  }
//
